(() => {
  const installSummaryAutoOpenGuard = () => {
    const guardKey = '__codexWideSummaryAutoOpenGuard';
    if (window[guardKey]) {
      window[guardKey].scan();
      return;
    }

    const openStates = new WeakMap();
    const manualIntents = new WeakMap();
    let scanScheduled = false;

    const isSummaryToggle = (element) => {
      if (!(element instanceof HTMLButtonElement)) return false;
      if (!element.hasAttribute('aria-pressed')) return false;
      const label = [
        element.getAttribute('aria-label'),
        element.getAttribute('title'),
      ].filter(Boolean).join(' ');
      return /摘要|summary/i.test(label);
    };

    const scan = () => {
      scanScheduled = false;
      document.querySelectorAll('button[aria-pressed]').forEach((button) => {
        if (!isSummaryToggle(button)) return;

        const isOpen = button.getAttribute('aria-pressed') === 'true';
        const wasOpen = openStates.get(button) === true;
        if (isOpen && !wasOpen) {
          const intentTime = manualIntents.get(button);
          const openedManually = typeof intentTime === 'number' &&
            performance.now() - intentTime < 1500;

          openStates.set(button, true);
          manualIntents.delete(button);
          if (!openedManually) button.click();
          return;
        }

        openStates.set(button, isOpen);
        if (!isOpen) manualIntents.delete(button);
      });
    };

    const scheduleScan = () => {
      if (scanScheduled) return;
      scanScheduled = true;
      window.queueMicrotask(scan);
    };

    document.addEventListener('click', (event) => {
      if (!event.isTrusted || !(event.target instanceof Element)) return;
      const button = event.target.closest('button[aria-pressed]');
      if (!isSummaryToggle(button)) return;
      if (button.getAttribute('aria-pressed') !== 'true') {
        manualIntents.set(button, performance.now());
      }
    }, true);

    const observer = new MutationObserver(scheduleScan);
    observer.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ['aria-label', 'aria-pressed', 'title'],
      childList: true,
      subtree: true,
    });

    window[guardKey] = { observer, scan: scheduleScan };
    scheduleScan();
  };

  const apply = () => {
    const id = 'codex-wide-width-override';
    let style = document.getElementById(id);
    if (!style) {
      style = document.createElement('style');
      style.id = id;
      (document.head || document.documentElement).appendChild(style);
    }
    style.textContent = $cssJson;
    $widthGuardSource
    if ($PreventSummary) installSummaryAutoOpenGuard();
    return true;
  };
  if (document.head || document.documentElement) return apply();
  document.addEventListener('DOMContentLoaded', apply, { once: true });
  return true;
})();

zcode.css:
:root,
body,
body *:not(.xterm, .xterm *) {
    font-size: ${ContentFontSize}px !important;
}

:root,
:host {
    --font-sans: $cssFontFamily !important;
    --font-mono: $cssFontFamily !important;
    --default-font-family: $cssFontFamily !important;
    --default-mono-font-family: $cssFontFamily !important;
}

html,
body,
button,
input,
select,
textarea {
    font-family: $cssFontFamily !important;
}

code,
kbd,
pre,
samp,
.font-mono,
.font-sans {
    font-family: $cssFontFamily !important;
}

/* 新建和已有会话统一使用配置宽度。 */
[data-v4-timeline-content-column="true"],
[data-v4-composer-dock-content="true"] {
    width: min(100%, $safeWidth) !important;
    max-width: $safeWidth !important;
    /* 取消为右侧状态面板预留空间的水平偏移。 */
    translate: none !important;
    transform: none !important;
}

/* 新建会话的输入组件也需解除内部宽度限制，与外层同步。 */
[data-v4-composer-dock-content="true"] [data-testid="v4-composer"] {
    width: 100% !important;
    max-width: 100% !important;
}

/* 左侧栏与右侧主区域使用相同的主题背景色。 */
[data-workspace-sidebar-panel="true"],
[data-testid="sidebar"] {
    background: var(--color-background) !important;
}

/* 工作区贴边显示，消除主面板四周露出的灰色底框。 */
[data-workspace-shell="true"] {
    --workspace-panel-radius: 0px !important;
}
[data-workspace-shell="true"] > [data-panel][id="content"] {
    padding: 0 !important;
}
[data-workspace-shell="true"] > [data-panel][id="content"] > .h-1\.5 {
    height: 0 !important;
}

/* 分隔线仅占 1px，透明热区仍保留足够的拖拽宽度。 */
[data-workspace-shell="true"] > [role="separator"][aria-controls="sidebar"] {
    width: 1px !important;
    background: var(--color-border) !important;
}
[data-workspace-shell="true"] > [role="separator"][aria-controls="sidebar"]::before {
    content: "";
    position: absolute;
    inset: 0 -4px;
    cursor: ew-resize;
}
[data-workspace-shell="true"] > [role="separator"][aria-controls="sidebar"] > [data-sidebar-divider-extension] {
    width: 1px !important;
}

